# Build/runtime environment for the video/ pipeline's Manim venv.
#
# manimpango has no Linux wheel on PyPI (only macOS/Windows) and this machine
# has runtime pango/cairo libraries but not the -dev headers, with no sudo to
# install libpango1.0-dev. Julia's own Pango_jll/Cairo_jll/... artifacts under
# ~/.julia/artifacts ship full relocatable headers + .pc files + shared libs
# (they are how Julia's Plots.jl gets a working Cairo backend with no root
# access either), so we point pkg-config and the linker at those instead of
# building anything from source ourselves. Two gaps remain even with them:
#   - glib.pc lists a hard Requires.private on libpcre2-8, but Julia never
#     downloaded a PCRE2_jll .pc file. The system HAS the runtime .so
#     (libpcre2-8.so.0, no -dev) so .pcshim/libpcre2-8.pc is a 4-line stub
#     that links straight to that soname.
#   - Julia's Glib_jll was built expecting a real GNU libintl (glibc already
#     implements those symbols itself, so nothing calls the stub at runtime),
#     resolved by pointing LD_LIBRARY_PATH at the one real Gettext_jll
#     artifact that happens to be on disk (searched for by its libintl.so.8
#     soname) rather than inventing another shim.
# Source this before any video/.venv pip install or manim/python invocation:
#   source video/env.sh
export PKG_CONFIG_PATH="/home/tony-zhang/Research/landmark_planning/video/.pcshim:/home/tony-zhang/.julia/artifacts/06a5c4a798cfe807193bbcaaae5a8333a280c342/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/0878d3462f8e2fa4193e0e47c530a58bc490a847/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/08db884c568df7d8a82ec8d230568af2aa414513/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/0a1006d282bce91b5cd408c714cbb95d3bb4f515/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/0b6297f066cea2e58184e355e1579094fec3099b/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/0ecdcf67bd5c1db95253c03ab63d57e40d0b4886/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/12a0dd5d0febd008900bbf169a86eab167574d77/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/1a7a9b96fbc256ab76474d09853a33d5fce4ece3/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/1da0de0a96a725c862d7ac253107e80a8d6d6a25/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/1fc51e89c2ef077489f58225de48d83b24038e59/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/22d553df4fb94c728edfc64d40dc74a2686494d0/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/258f7271ca555a7634c0fe8b8508f69334673a89/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/299dd9a174ebc497df2cf4d30f1c6d10948c60ef/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/29c0d7a5be41c9f6969895d7725cd7adacb59890/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/336927c1465199d13e7eb42eb2716c60d41237fe/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/33f5589f1ac22f399e59bab964eb85fa298f21e5/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/353f5c4e091a41ba8da5297d1b4d13652aa7f775/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/37cb7108fbb589ecbd0b1a556668cb61a929388b/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/38e215c51e5c0f77bc7a8813ba4586632a8fc750/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/39e01e7ef8081eb70f4f0c29407b8251fa96c46f/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/3d40b81fac6f43120cb43982b5fda773bcf44a4b/lib/pkgconfig:/home/tony-zhang/.julia/artifacts/3e126c2ea988345